BEGIN READ ONLY;
SELECT jsonb_build_object(
 'captured_at',clock_timestamp(),
 'placeholder_variant_images',(SELECT count(*) FROM catalog.variant_images WHERE url LIKE 'https://placehold.co/%'),
 'products_without_image',(SELECT count(*) FROM catalog.products p WHERE NOT EXISTS(SELECT 1 FROM catalog.product_images i WHERE i.product_id=p.id)),
 'variants_without_image',(SELECT count(*) FROM catalog.variants v WHERE NOT EXISTS(SELECT 1 FROM catalog.variant_images i WHERE i.variant_id=v.id)),
 'simple_required_attributes_missing',(SELECT count(*) FROM catalog.products p JOIN taxonomy.product_type_characteristics a ON a.tipo_producto_id::text=p.tipo_producto_id AND a.estado='ACTIVO' AND a.obligatoria WHERE NOT p.tiene_variantes AND NOT EXISTS(SELECT 1 FROM catalog.product_attribute_values v WHERE v.product_id=p.id AND v.caracteristica_id=a.caracteristica_id::text)),
 'variant_required_attributes_missing',(SELECT count(*) FROM catalog.variants v JOIN catalog.products p ON p.id=v.product_id JOIN taxonomy.product_type_characteristics a ON a.tipo_producto_id::text=p.tipo_producto_id AND a.estado='ACTIVO' AND a.obligatoria WHERE NOT EXISTS(SELECT 1 FROM catalog.variant_attribute_values x WHERE x.variant_id=v.id AND x.caracteristica_id=a.caracteristica_id::text)),
 'identifying_associations_missing',(SELECT count(*) FROM (SELECT DISTINCT v.product_id,a.caracteristica_id FROM catalog.variants v JOIN catalog.variant_attribute_values a ON a.variant_id=v.id AND a.es_identificador) expected WHERE NOT EXISTS(SELECT 1 FROM catalog.product_identifying_characteristics x WHERE x.product_id=expected.product_id AND x.caracteristica_id=expected.caracteristica_id)),
 'invalid_list_value_references',(SELECT count(*) FROM (SELECT caracteristica_id,valor_id FROM catalog.product_attribute_values UNION ALL SELECT caracteristica_id,valor_id FROM catalog.variant_attribute_values) a JOIN taxonomy.characteristics c ON c.id::text=a.caracteristica_id AND c.tipo='LISTA' WHERE NOT EXISTS(SELECT 1 FROM taxonomy.characteristic_values v WHERE v.id::text=a.valor_id AND v.caracteristica_id::text=a.caracteristica_id AND v.estado='ACTIVO')),
 'parent_profiles',(SELECT count(*) FROM catalog.sku_physical_profiles f JOIN catalog.sku_identity s ON s.id=f.sku_identity_id JOIN catalog.products p ON p.id=s.product_id WHERE p.tiene_variantes),
 'physical_distribution',(SELECT jsonb_build_object('variant',count(*) FILTER(WHERE s.variant_id IS NOT NULL),'simple',count(*) FILTER(WHERE s.product_id IS NOT NULL)) FROM catalog.sku_physical_profiles f JOIN catalog.sku_identity s ON s.id=f.sku_identity_id),
 'physical_values_text',(SELECT jsonb_agg(jsonb_build_object('sku',s.sku,'sku_identity_id',s.id,'profile_id',f.id,'peso_kg',f.peso_kg::text,'largo_cm',f.largo_cm::text,'ancho_cm',f.ancho_cm::text,'alto_cm',f.alto_cm::text) ORDER BY s.sku) FROM catalog.sku_physical_profiles f JOIN catalog.sku_identity s ON s.id=f.sku_identity_id),
 'storage',(SELECT jsonb_agg(jsonb_build_object('id',id,'name',name,'etag',metadata->>'eTag','bytes',metadata->>'size','mimetype',metadata->>'mimetype') ORDER BY name) FROM storage.objects WHERE bucket_id='catalog-products'),
 'storage_permissions',jsonb_build_object('schema_usage',has_schema_privilege('po_catalog_owner','storage','USAGE'),'objects_select',has_table_privilege('po_catalog_owner','storage.objects','SELECT'),'buckets_select',has_table_privilege('po_catalog_owner','storage.buckets','SELECT'))
) AS final_quality; COMMIT;
